// Calculation group: 'Time Intelligence'  (Format = None on the group itself)
// Calculation item 1: "YTD"  (Ordinal = 0)
CALCULATE (
    SELECTEDMEASURE (),
    DATESYTD ( 'Date'[Date] )
)

// Calculation item 2: "PY"  (Ordinal = 1)
CALCULATE (
    SELECTEDMEASURE (),
    SAMEPERIODLASTYEAR ( 'Date'[Date] )
)

// Calculation item 3: "YoY %"  (Ordinal = 2)
// Format string expression for this item: "0.0%;-0.0%;0.0%"
VAR CurrentValue = SELECTEDMEASURE ()
VAR PriorValue =
    CALCULATE (
        SELECTEDMEASURE (),
        SAMEPERIODLASTYEAR ( 'Date'[Date] )
    )
RETURN
    DIVIDE ( CurrentValue - PriorValue, PriorValue )

